// The playable state: real geography (outline, coast, rivers, lakes, mountains, cities, highways) loaded from
// state.json and compressed by a scale factor, with full-size cities generated by CityLayout. Provides the
// terrain height field the engine builds its landscape from, and merges every city, highway and venue into one
// world CityPlan. World axes: X east, Y south, metres; the start city sits near the origin.
#pragma once

#include "Sim/CityLayout.h"
#include "Sim/Json.h"
#include "Sim/SimCommon.h"

#include <array>
#include <string>
#include <vector>

namespace dtg::sim
{
	using Point2 = std::array<double, 2>;

	struct StateCity
	{
		std::string Name;
		double X = 0.0;
		double Y = 0.0;
		CityStyle Style = CityStyle::Town;
		int Grid = 3;
		bool bStart = false;
		std::vector<std::pair<LotRole, std::string>> Landmarks;
		double LevelM = 0.0;        // ground height the city is built on
		Rect Bounds;                // footprint including its outer roads
	};

	struct StateLake
	{
		std::string Name;
		double X = 0.0;
		double Y = 0.0;
		double RadiusM = 200.0;
		double LevelM = 0.0;        // water surface height
	};

	struct StateRiver
	{
		std::string Name;
		double WidthM = 8.0;
		std::vector<Point2> Points;
	};

	struct StateVenue
	{
		EventKind Kind = EventKind::DragRace;
		std::string Name;
		double X = 0.0;
		double Y = 0.0;
		double LevelM = 0.0;
	};

	/** What lies at a point, for water rendering and gameplay (swimming, bridges). */
	struct SurfaceInfo
	{
		double GroundM = 0.0;
		bool bWater = false;
		double WaterM = 0.0;
		bool bOcean = false;
		double RoadGradeM = 0.0;  // the graded surface a road deck follows (equals GroundM on land)
	};

	class StatePlan
	{
	public:
		bool Load(const JsonValue& Root, std::vector<std::string>& Errors);

		std::string Name;
		std::string Abbreviation;
		double Scale = 25.0;
		double VerticalScale = 3.0;
		double OriginLon = 0.0;
		double OriginLat = 0.0;
		std::vector<Point2> Outline;
		int CoastStart = 0;
		int CoastEnd = 0;
		std::vector<Point2> Mountains;
		double PeakMeters = 1000.0;
		std::vector<StateCity> Cities;
		std::vector<StateLake> Lakes;
		std::vector<StateRiver> Rivers;
		std::vector<HighwayPlan> Highways;
		std::vector<StateVenue> Venues;
		std::vector<VenuePlan> VenueLayouts; // laid out at each venue's final position (same order as Venues)
		Rect Bounds;

		Point2 ToWorld(double Lon, double Lat) const;
		const StateCity* StartCity() const;
		const StateCity* FindCity(const std::string& CityName) const;
		bool InsideState(double X, double Y) const;
		/** Distance to the coastline (metres, world). */
		double CoastDistance(double X, double Y) const;
		bool IsOcean(double X, double Y) const;

		/** Terrain height before cities, roads and water are carved in (world metres). */
		double NaturalHeight(double X, double Y) const;
		/** Final ground height: flattened under cities, venues and roads, carved for rivers, lakes and the sea. */
		SurfaceInfo SurfaceAt(double X, double Y) const;
		double HeightAt(double X, double Y) const { return SurfaceAt(X, Y).GroundM; }
		/** Road surface height: a highway's deck profile on a highway, else the ground (or just above water). */
		double RoadHeightAt(double X, double Y) const;

		/** Generates every city and merges them with highways and venues into one world plan. */
		CityPlan BuildWorld(const CityConfig& HubTemplate) const;

	private:
		void PlaceCities();
		void PlaceVenues();
		void BuildSea();
		void DetourAroundCities();
		void JoinCrossings();
		void ComputeDecks();
		void HarmonizeLevels();
		bool FootprintOnLand(const StateCity& City) const;
		/** Inside the level pad of a city or venue. */
		bool InsideFlattened(double X, double Y) const;
		void RouteHighways(const std::vector<std::pair<std::string, std::vector<JsonValue>>>& Routes, const std::vector<bool>& Interstate,
			std::vector<std::string>& Errors);
		double Noise(double X, double Y, double Wavelength) const;
		Rect CityRect(const StateCity& City, double Margin = 0.0) const;
		/** Distance from a point to a rect (0 inside). */
		static double RectDistance(const Rect& Area, double X, double Y);
		static double SegmentDistance(const Point2& A, const Point2& B, double X, double Y, double* OutT = nullptr);
		/** Height a road is graded to at a polyline vertex: the level of a city or venue it enters, else the land. */
		double AnchorHeight(const Point2& Where) const;
		/** Nearest point on the state outline. */
		Point2 NearestBorderPoint(double X, double Y) const;
		std::uint64_t Seed = 1977;
		std::vector<Point2> Sea; // coast extended past both ends and closed offshore
	};

	/** Block pitch used for every city (block + road), so city footprints can be computed before generation. */
	double CitySpan(int Grid, double BlockSize = 110.0, double RoadWidth = 18.0);
}
